    "F26B9/06": {
      "code": "F26B9/06",
      "level": 8,
      "parent": "F26B9/00",
      "ja": "静止したドラムまたは小室におけるもの．｛注．．このグループにおいては，＋ＩＤＴという表現は以下の内容を意味する。．　－ここに分類されている文献は，被乾燥物が移動されないものであり，物品，例．木材の回分乾燥が固定位置の換気装置を使用する物品上または中を流れるガス媒体で行われる乾燥小室または密閉体に関連するＩＤＴ－グループに分類されていた:．　－それらは上記ＩＤＴーグループからこのグループに管理上再分類されていた｝",
      "en": "in stationary drums or chambers",
      "count": 6723,
      "ipcCode": "F26B9/06",
      "coreCode": "F26B9/06",
      "note": "",
      "sourceFile": "cpc_F26B.txt",
      "kind": "cpc"
    },
